const tabId = 118779795;
const storeCards = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('main li')).filter(li => li.innerText?.includes('miles away'));
  return items.map(li => {
    const title = li.querySelector('h2, [class*="title"], [class*="heading"]')?.innerText?.trim();
    const btn = li.querySelector('button[data-lid*="Make This Your Store"], button:has-text("Make This Your Store"), button');
    const allBtns = Array.from(li.querySelectorAll('button')).map(b => b.innerText?.trim());
    return {
      title,
      text: li.innerText?.slice(0, 200),
      buttons: allBtns
    };
  });
});
console.log(JSON.stringify(storeCards, null, 2));

